def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    camMgr = adsk.cam.CAMManager.get()
    libMgr = camMgr.libraryManager
    toolLibs = libMgr.toolLibraries
    # search all libraries for one named TIW
    def walk(url, depth=0):
        found = []
        for child in toolLibs.childAssetURLs(url):
            found.append(child)
            found += walk(child, depth+1)
        return found
    roots = [toolLibs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation),
             toolLibs.urlByLocation(adsk.cam.LibraryLocations.Fusion360LibraryLocation),
             toolLibs.urlByLocation(adsk.cam.LibraryLocations.CloudLibraryLocation)]
    for r in roots:
        try:
            for u in walk(r):
                if 'TIW' in u.toString() or 'tiw' in u.toString().lower():
                    print("Found lib URL:", u.toString())
        except Exception as e:
            print("err", e)
    return "ok"

